simple='''def transform(grid):
    out=[row[:] for row in grid]
    points=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==2]
    if len(points)<2:
        return out
    # Use the longest axis-aligned pair as the main segment.
    choices=[]
    for i,(r1,c1) in enumerate(points):
        for r2,c2 in points[i+1:]:
            if r1==r2:
                choices.append((abs(c2-c1),0,(r1,min(c1,c2)),(r1,max(c1,c2))))
            if c1==c2:
                choices.append((abs(r2-r1),1,(min(r1,r2),c1),(max(r1,r2),c1)))
    if choices:
        _,axis,a,b=max(choices,key=lambda x:(x[0],-x[1]))
        r1,c1=a; r2,c2=b
        if axis==0:
            for c in range(c1,c2+1):
                if out[r1][c]==0: out[r1][c]=3
            for r,c in points:
                if r==r1: continue
                cc=min(max(c,c1),c2)
                # Connect perpendicularly to the backbone, then along it if beyond an endpoint.
                for rr in range(min(r,r1),max(r,r1)+1):
                    if out[rr][c]==0: out[rr][c]=3
                for x in range(min(c,cc),max(c,cc)+1):
                    if out[r1][x]==0: out[r1][x]=3
        else:
            for r in range(r1,r2+1):
                if out[r][c1]==0: out[r][c1]=3
            for r,c in points:
                if c==c1: continue
                rr=min(max(r,r1),r2)
                for cc in range(min(c,c1),max(c,c1)+1):
                    if out[r][cc]==0: out[r][cc]=3
                for y in range(min(r,rr),max(r,rr)+1):
                    if out[y][c1]==0: out[y][c1]=3
    else:
        # No aligned pair: connect points to a common median cross.
        rs=sorted(r for r,c in points); cs=sorted(c for r,c in points)
        mr=rs[(len(points)-1)//2]; mc=cs[(len(points)-1)//2]
        for r,c in points:
            for cc in range(min(c,mc),max(c,mc)+1):
                if out[r][cc]==0: out[r][cc]=3
            for rr in range(min(r,mr),max(r,mr)+1):
                if out[rr][mc]==0: out[rr][mc]=3
    return out
'''
